mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.2) * p.xz;
  vec3 offset = p;
  float dr = 1.0;
  float scale = 2.4;
  for (int i = 0; i < 4; i++) {
    p = clamp(p, -1.0, 1.0) * 2.0 - p;
    float r2 = dot(p, p);
    if (r2 < 0.25) {
      float k = 4.0; p *= k; dr *= k;
    } else if (r2 < 1.0) {
      float k = 1.0 / r2; p *= k; dr *= k;
    }
    p = p * scale + offset;
    dr = dr * abs(scale) + 1.0;
  }
  return (length(p) - 1.2) / dr;
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.2);
  vec3 rd = normalize(vec3(p, 1.5));
  float t = 0.0;
  for (int i = 0; i < 45; i++) {
    float d = map(ro + rd * t);
    if (d < 0.002 || t > 7.0) break;
    t += d * 0.7;
  }
  vec3 col = vec3(0.02, 0.03, 0.04);
  if (t < 7.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.003, 0.0);
    vec3 n = normalize(vec3(
      map(pos + e.xyy) - map(pos - e.xyy),
      map(pos + e.yxy) - map(pos - e.yxy),
      map(pos + e.yyx) - map(pos - e.yyx)
    ));
    vec3 l = normalize(vec3(1.0, 1.5, -1.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 32.0);
    col = vec3(0.08, 0.1, 0.12) + diff * vec3(0.6, 0.7, 0.8) + spec * vec3(1.0, 0.95, 0.8);
  }
  ret = col;
}
